import { useState } from 'react';

export default function App() {
  const [msg, setMsg] = useState('');
  function greet(name, e) {
    console.log(e.type);
    setMsg(`Hello ${name}!`);
  }
  return (
    <div>
      {['React', 'Vue', 'Angular'].map((fw) => (
        <button key={fw} type="button" className="greet" onClick={(e) => greet(fw, e)}>{fw}</button>
